import './style.css';
import {ladders,nextLadderStep} from './ladders';
import {mergeLeetCode,validLeetCode} from './leetcode';
import {mountEditor,disposeEditor,starter,showDiagnostics,copyCode,pasteCode,selectAllCode,replaceCode} from './editor';
import {topics,topicById,academyUrl} from './topics';
import {progress,reviews,plan,elapsed,localDay,qualified,key,verifyLogs,validState,DAY,candidates,ratingLadders,trackProfile,savedSolution,completionEvidence,categoryProblems,repeatCandidate} from './engine';
import type {State,Problem,Catalog,Profile,Outcome} from './types';
const $=<T extends HTMLElement=HTMLElement>(selector:string)=>document.querySelector<T>(selector)!;
const escape=(value:unknown)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const icon=(name:string)=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16"/>',book:'<path d="M12 5C9 3 5 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 1Zm0 0v16"/>',repeat:'<path d="m17 2 4 4-4 4M3 11V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14-1v3a2 2 0 0 1-2 2H3"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8V5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--surface)"/><circle cx="16" cy="17" r="3" fill="var(--surface)"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H4v17h17v-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',play:'<path d="m9 5 11 7-11 7Z"/>',leaf:'<path d="M19 3C5 2 3 9 6 15s14 4 13-12ZM5 21 15 9"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>'} as Record<string,string>)[name]||''}</svg>`;
const formatTime=(n:number)=>`${Math.floor(Math.max(0,n)/60).toString().padStart(2,'0')}:${Math.floor(Math.max(0,n)%60).toString().padStart(2,'0')}`;
const shortDate=(n:number)=>new Date(n).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const link=(url:string,label:string)=>`<a href="${escape(url)}" data-external="${escape(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
let state:State,catalog:Catalog,view='today',filterTopic='',filterRating='all',filterStatus='unsolved',query='',focusTopic='',busy=false,reflection=false,storageBroken=false;
let handleDraft:string|null=null;
let reviewFilter='due';
let leetcodeDraft:string|null=null,leetcodeBusy=false,selectedLadder='';
let evidenceTopic='implementation',evidenceBand='all',categoryScope='all';
let toastTimer:ReturnType<typeof setTimeout>;
function toast(text:string){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
let writes:Promise<unknown>=Promise.resolve();
function save(){
 if(storageBroken)return;
 const json=JSON.stringify(state);
 writes=writes.catch(()=>{}).then(()=>window.fieldwork?window.fieldwork.save(json):localStorage.setItem('fieldwork-v1',json)).catch(()=>{storageBroken=true;toast('Progress could not be saved. Export a backup from Settings before closing.');});
}
function openExternal(url:string){
 try{
  const parsed=new URL(url);
  if(parsed.hostname==='codeforces.com'&&parsed.pathname.startsWith('/problemset/problem/'))parsed.searchParams.set('locale','en');
  url=parsed.href;
 }catch{}
 if(window.fieldwork)void window.fieldwork.open(url).catch(e=>toast(e.message));else window.open(url,'_blank','noopener,noreferrer');
}
function recommendation(){return plan(state,catalog.problems,Date.now(),focusTopic||undefined);}
function problem(id:string){return catalog.problems.find(p=>p.id===id);}
function problemLadderLink(id:string){const ladder=ladders.find(l=>l.steps.some(step=>step.codeforcesIds.includes(id)));return ladder?`<button class="text-button" data-ladder="${ladder.id}">Concept ladder ${icon('arrow')}</button>`:'';}
function rated(p:Problem){return `<span class="rating">${p.rating}</span>`;}
function status(p:Problem){return state.profile.solved.some(s=>key(s)===p.id)?'Accepted':state.logs.some(l=>l.problemId===p.id)?'Practiced':'Unseen';}
function shell(content:string){
 disposeEditor();
 const due=reviews(state).filter(r=>r.due).length;
 const nav=[['today','sun','Today'],['map','map','Skill map'],['ladders','leaf','Concept ladders'],['library','book','Problem library'],['reviews','repeat','Review queue'],['journal','chart','Progress']];
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#today"><span class="brand-mark">${icon('leaf')}</span>fieldwork<span class="brand-dot">.</span></a><div class="workspace-label">YOUR PRACTICE SPACE</div><nav>${nav.map(([id,i,label])=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}">${icon(i)}<span>${label}</span>${id==='reviews'&&due?`<span class="nav-count">${due}</span>`:''}</button>`).join('')}</nav><div class="sidebar-sync"><button class="button secondary wide" data-action="sync-current" ${busy?'disabled':''}>${icon('repeat')}${busy?'Syncing…':'Sync Codeforces'}</button><p class="tiny">Last synced ${escape(new Date(state.profile.syncedAt).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))}</p><button class="button secondary wide" data-action="sync-leetcode-current" ${leetcodeBusy?'disabled':''}>${icon('repeat')}${leetcodeBusy?'Syncing LeetCode…':state.leetcode?'Sync LeetCode':'Connect LeetCode'}</button></div><div class="sidebar-bottom"><div class="sidebar-note"><span class="tiny-label">THE LONG GAME</span><p>A little sharper.<br>Every day.</p><div class="tiny">Built for a life beyond the editor.</div></div><button class="nav-item ${view==='settings'?'active':''}" data-view="settings">${icon('settings')}<span>Settings & data</span></button><div class="profile"><div class="avatar">${escape(state.profile.handle.slice(0,1).toUpperCase())}</div><div><strong title="${escape(state.profile.handle)}">${escape(state.profile.handle)}</strong><span>Codeforces · ${state.profile.rating??'Unrated'}</span></div><span class="online-dot" title="Local workspace"></span></div></div></aside><div class="main-shell"><header class="topbar"><span>Personal training / <strong>${view==='session'?'Focus session':({today:'Today',map:'Skill map',library:'Problem library',reviews:'Review queue',journal:'Progress',settings:'Settings',evidence:'Category problems',ladders:'Concept ladders'} as Record<string,string>)[view]}</strong></span><span class="local-badge"><span class="online-dot"></span>${window.fieldwork?'Desktop workspace':'Browser preview'}</span></header><main>${content}</main><footer><span>Small steps. Strong foundations.</span><span>Codeforces + LeetCode · Concept-led practice</span></footer></div>`;
 bind();updateClock();
 const codeHost=$('#code-editor');if(codeHost&&state.active)mountEditor(codeHost,state.active.code??starter,code=>{state.active!.code=code;save();},toast);
}
function heading(kicker:string,title:string,sub:string,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;}
function bandStats(){const all=topics.map(t=>progress(state,t.id));return {covered:all.filter(p=>p.attempts).length,cleared:all.filter(p=>p.cleared!==null).length};}
function today(){
 const next=recommendation(),stats=bandStats(),todayLogs=state.logs.filter(l=>localDay(l.finishedAt)===localDay(Date.now()));
 const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-d.getDay()+((d.getDay()===0)?-6:1)+i);return d;});
 const weekLogs=state.logs.filter(l=>week.some(d=>localDay(d.getTime())===localDay(l.finishedAt)));
 const minutes=Math.round(weekLogs.reduce((s,l)=>s+l.seconds/60,0));
 const topic=next?.topic;
 shell(`${heading(new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase(),todayLogs.length?'A little stronger already.':'Make room for one good problem.',todayLogs.length?'Your session is logged. Stop here, or keep going if you have the time.':'A focused session, a useful lesson, and then back to your day.',`<div class="heading-flower">✳</div>`)}
 <div class="today-grid"><div class="today-left"><section class="hero-card"><div class="hero-top"><span class="pill"><span class="online-dot"></span>${state.active?'SESSION IN PROGRESS':next?.review?'RETRIEVAL PRACTICE':'YOUR NEXT SMALL STEP'}</span><span class="muted">${icon('clock')} 30–60 min</span></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><div class="orbit-core">↗</div><span class="orbit-node n1"></span><span class="orbit-node n2"></span><span class="orbit-node n3"></span></div><div class="hero-copy"><h2>${state.active?'Pick up where<br>you left off.':next?`Build your<br><em>${escape(topic!.name.toLowerCase())}.</em>`:'Your next step<br>needs a refresh.'}</h2><p>${state.active?'Your timer, notes, and checklist are saved.':next?escape(next.reason):'No unseen problems remain at the exact current bands. Refresh the catalog, revisit a problem, or try a different category.'}</p></div><div class="session-length"><span>Time you have</span><div class="segmented">${[30,45,60].map(m=>`<button data-duration="${m}" class="${state.duration===m?'selected':''}" aria-pressed="${state.duration===m}">${m} min</button>`).join('')}</div></div><div class="hero-actions"><button class="button primary" data-action="start" ${!next&&!state.active?'disabled':''}>${icon('play')}${state.active?'Resume session':todayLogs.length?'Keep the momentum':'Start my session'}${icon('arrow')}</button><button class="text-button" data-action="choose">Choose a category ${icon('arrow')}</button></div><div class="hero-footer">One problem at a time. Extend the session whenever you want.</div></section>
 <section class="section"><div class="section-heading"><h2>The shape of your session</h2><span>${state.duration} minutes, with a clear finish</span></div><div class="steps"><div><span class="step-number">01</span><span class="tiny-label">RECALL · 5 MIN</span><h3>Bring an idea back</h3><p>Explain a recent pattern before looking at your notes.</p></div><div><span class="step-number">02</span><span class="tiny-label">SOLVE · ${state.duration-10} MIN</span><h3>Find your next insight</h3><p>Reason, code, test. Check your progress at 25 minutes.</p></div><div><span class="step-number">03</span><span class="tiny-label">REFLECT · 5 MIN</span><h3>Keep what you learned</h3><p>Record the blocker. Schedule a fresh attempt.</p></div></div></section>
 <section class="card next-card"><div class="section-heading"><h2>${next?.review?'Coming back to':'On your desk today'}</h2><span class="tiny-label">${next?.review?'REVIEW':'CODEFORCES'}</span></div>${next?`<div class="problem-preview"><span class="problem-symbol">${topic!.icon}</span><div><h3>${escape(next.problem.name)}</h3><p>${next.problem.id} <span class="dot-separator">·</span> ${escape(topic!.name)} <span class="dot-separator">·</span> ${next.review?'Previously practiced':'Not yet accepted'}</p></div>${rated(next.problem)}</div><div class="why">${icon('leaf')}<span>Exact ${next.problem.rating} band. ${next.review?'Recall it before reopening the explanation.':'Selected for steady progress in this category.'}</span></div>`:'<p class="muted">Use the library to choose a review while you refresh the catalog.</p>'}</section></div>
 <aside class="today-right"><section class="card week-card"><div class="section-heading"><h2>A week of showing up</h2>${icon('sun')}</div><div class="week-days">${week.map(d=>{const done=weekLogs.some(l=>localDay(l.finishedAt)===localDay(d.getTime()));return `<div class="week-day"><span>${d.toLocaleDateString(undefined,{weekday:'narrow'})}</span><div class="day-circle ${done?'done':''} ${localDay(d.getTime())===localDay(Date.now())?'current':''}">${done?icon('check'):d.getDate()}</div></div>`;}).join('')}</div><div class="week-total"><strong>${minutes}<small> min</small></strong><span>of a flexible<br>240–360 min week</span></div><div class="progress-track"><i style="width:${Math.min(100,minutes/240*100)}%"></i></div><p class="tiny">A missed day is just a day. Start again today.</p></section><section class="card growth-card"><span class="tiny-label">YOUR TRAINING BASELINE</span><div class="baseline"><strong>${state.profile.rating??'—'}</strong><span class="pill subtle">Codeforces rating</span></div><p>Practice bands advance separately in each category.</p><div class="metric-row"><span>Categories explored</span><strong>${stats.covered} <span>/ ${topics.length}</span></strong></div><div class="metric-row"><span>Categories with a cleared band</span><strong>${stats.cleared}</strong></div><button class="text-button wide" data-view="map">See your skill map ${icon('arrow')}</button></section><section class="reference-card"><div class="reference-icon">↗</div><span class="tiny-label">A MAP, NOT A CHECKLIST</span><h3>Inspired by the Academy.</h3><p>Broad topic coverage, one manageable Codeforces rating at a time.</p>${link(academyUrl,`Explore the topic reference ${icon('external')}`)}</section></aside></div>`);
}
function skillMap(){
 shell(`${heading('STEADY PROGRESS, IN EVERY DIRECTION','Your skill map.','Each category earns its next rating band. A hard solve in one area never inflates another.')}<div class="rules-banner"><div>${icon('check')}<strong>The rule for moving up</strong></div><p>3 distinct independent accepted solves at the exact band, each within 25 minutes, plus 1 accepted repeat after 48 hours. Reasoning and test checks required. Helped solves go to review.</p></div><div class="map-grid">${topics.map(t=>{const p=progress(state,t.id);const historical=state.profile.solved.filter(s=>s.tags.some(tag=>t.tags.includes(tag)));const available=candidates(state,catalog.problems,t,p.band).length;const repeat=repeatCandidate(state,catalog.problems,t.id);return `<article class="card skill-card" data-category-card="${t.id}"><div class="skill-head"><span class="topic-icon">${t.icon}</span><span class="tiny-label">${escape(t.group)}</span></div><h3><button class="category-title" data-evidence="${t.id}">${t.name}</button></h3><p>${t.description}</p><div class="skill-band"><strong>${p.band}</strong><span>practice band<br><small>${p.cleared===null?'Not yet calibrated':`Last cleared: ${p.cleared}`}</small></span></div><div class="evidence-dots">${[0,1,2].map(i=>`<span class="${i<p.fresh?'filled':''}">${i<p.fresh?'✓':i+1}</span>`).join('')}<button class="repeat-dot ${p.reviewed?'filled':''}" data-repeat="${t.id}" ${repeat?'':'disabled'} title="${repeat?'Start an eligible repeat':p.fresh<3?'Complete three problems first':'Wait 48 hours after a qualifying solve'}" aria-label="${repeat?'Start repeat': 'Repeat not ready'}">↻</button><small>${p.fresh}/3 + review</small></div><div class="skill-history">${historical.length} historical accepts · ${available} unseen at this band</div><button class="button primary wide" data-evidence="${t.id}">View category ${icon('arrow')}</button><button class="text-button wide" data-train="${t.id}" ${available===0&&!reviews(state).some(r=>r.log.topicId===t.id&&r.due)?'disabled':''}>Start a practice problem ${icon('arrow')}</button></article>`;}).join('')}</div><p class="footnote">Categories are an app-specific grouping of Codeforces tags, inspired by the Academy’s sections. Tags can overlap and do not prove which technique you used. Only the selected focus category receives credit. Historical accepts are context, not verified independent mastery. A band needs at least 3 rated problems in the catalog: sparse bands are unavailable and never marked cleared. Trees, disjoint sets, and shortest paths therefore start higher.</p>`);
}
function library(){
 const solved=new Set(state.profile.solved.map(key));
 const list=catalog.problems.filter(p=>(!filterTopic||p.tags.some(t=>topicById(filterTopic).tags.includes(t)))&&(filterRating==='all'||p.rating===Number(filterRating))&&(filterStatus==='all'||(filterStatus==='unsolved'?!solved.has(p.id):solved.has(p.id)))&&(`${p.name} ${p.id}`.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>a.rating-b.rating||b.solvedCount-a.solvedCount);
 shell(`${heading('A SMALL NEXT STEP, FROM A BIG LIBRARY','Find your next problem.','Official Codeforces ratings. Search the cached catalog or follow your daily recommendation.')}<div class="rules-banner"><div><strong>LeetCode + Codeforces</strong></div><p>Follow connected exercises through a concept ladder, with direct problem links on both platforms.</p><button class="button secondary small" data-view="ladders">Explore ladders ${icon('arrow')}</button></div><div class="filters"><label class="search-field">${icon('search')}<input id="search" type="search" placeholder="Search name or problem ID…" value="${escape(query)}" aria-label="Search problems"></label><label><span class="sr-only">Category</span><select id="topic-filter"><option value="">All categories</option>${topics.map(t=>`<option value="${t.id}" ${filterTopic===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label><label><span class="sr-only">Rating</span><select id="rating-filter"><option value="all">All ratings</option>${Array.from(new Set(catalog.problems.map(p=>p.rating))).sort((a,b)=>a-b).map(r=>`<option ${filterRating===String(r)?'selected':''}>${r}</option>`).join('')}</select></label><label><span class="sr-only">Problem status</span><select id="status-filter"><option value="unsolved" ${filterStatus==='unsolved'?'selected':''}>Not accepted</option><option value="all" ${filterStatus==='all'?'selected':''}>All problems</option><option value="solved" ${filterStatus==='solved'?'selected':''}>Accepted</option></select></label></div><div class="section-heading"><span>${list.length.toLocaleString()} matching problems · showing ${Math.min(80,list.length)}</span><span>Catalog ${shortDate(new Date(catalog.updatedAt).getTime())}</span></div><section class="card table-card"><table><thead><tr><th>Problem</th><th>Rating</th><th>Tags</th><th>Status</th><th></th></tr></thead><tbody>${list.slice(0,80).map(p=>`<tr><td><span class="problem-id">${p.id}</span><strong>${escape(p.name)}</strong></td><td>${rated(p)}</td><td class="table-tags">${escape(p.tags.slice(0,3).join(' · '))}</td><td><span class="status ${solved.has(p.id)?'accepted':''}">${status(p)}</span></td><td><button class="text-button" data-pick="${p.id}">Practice ${icon('arrow')}</button>${problemLadderLink(p.id)}</td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty"><h3>No matches at this filter.</h3><p>Try a different rating, category, or search term.</p></div>':''}</section>`);
}
function savedAttempts(problemId:string){
 const solution=savedSolution(state,problemId,starter);
 const source=solution?`<section class="saved-solution"><h3>Latest saved solution</h3><p class="tiny">${escape(new Date(solution.finishedAt).toLocaleString())} · Saved in Fieldwork</p><pre class="saved-code"><code>${escape(solution.code)}</code></pre><button class="button secondary small" data-copy-saved="${escape(solution.id)}">Copy saved code</button>${view==='session'?`<button class="button secondary small" data-restore-saved="${escape(solution.id)}">Load into editor (counts as help)</button>`:''}</section>`:'<p class="tiny">No solution code was saved in Fieldwork for this problem. Codeforces sync tracks acceptance; it does not import source code.</p>';
 return source+`<details class="attempt-log"><summary>Attempt history</summary>`+state.logs.filter(l=>l.problemId===problemId).sort((a,b)=>b.finishedAt-a.finishedAt).map(l=>`<article class="saved-attempt"><h4>${escape(new Date(l.finishedAt).toLocaleString())} · ${l.review?'Review':'Practice'} · ${escape(l.outcome)}</h4>${l.blocker?`<p>Main friction: ${escape(l.blocker)}</p>`:''}<p class="saved-notes">${escape(l.notes.trim()?l.notes:'No reflection was recorded for this attempt.')}</p>${l.code?.trim()&&l.code.trim()!==starter.trim()?`<details><summary>Code from this attempt</summary><pre class="saved-code"><code>${escape(l.code)}</code></pre></details>`:'<p class="tiny">No solution code recorded in this attempt (empty or starter only).</p>'}</article>`).join('')+'</details>';
}
function reviewQueue(){
 const all=reviews(state),queue=all.filter(r=>reviewFilter==='all'||(reviewFilter==='due'?r.due:!r.due));
 shell(`${heading('MAKE THE IDEA YOURS','The review queue.','One entry per problem. Solved problems return on their scheduled recall date.')}<div class="rules-banner"><div>${icon('repeat')}<strong>Spaced recall</strong></div><p>Acceptance and review are separate: an accepted solution can still be scheduled for recall. Completing a review moves its next date forward. Earlier code stays in the saved history.</p></div><div class="segmented review-filters">${[['due','Due now',all.filter(r=>r.due).length],['upcoming','Upcoming',all.filter(r=>!r.due).length],['all','All scheduled',all.length]].map(([id,label,count])=>`<button data-review-filter="${id}" class="${reviewFilter===id?'selected':''}" aria-pressed="${reviewFilter===id}">${label} (${count})</button>`).join('')}</div>${queue.length?`<section class="card">${queue.map(r=>{const p=problem(r.log.problemId),accepted=state.profile.solved.some(s=>key(s)===r.log.problemId)||!!state.profile.accepted[r.log.problemId]||r.log.verified;return `<div class="review-entry" data-review-problem="${escape(r.log.problemId)}"><div class="review-row"><div class="review-date ${r.due?'due':''}">${r.due?'Due now':shortDate(r.dueAt)}</div><div class="grow"><h3>${escape(p?.name||r.log.problemId)}</h3><p>${escape(r.log.problemId)} · ${topicById(r.log.topicId).name} · ${r.log.rating} · ${accepted?'Accepted on Codeforces · Scheduled recall':r.log.outcome==='independent'?'Solve recorded · Acceptance not synced':r.log.outcome==='assisted'?'Previously used help':'Unfinished last time'}</p></div><button class="button secondary small" data-review="${r.log.id}">${state.active?.problemId===r.log.problemId?'Resume session':r.due?'Start review':'Practice early'} ${icon('arrow')}</button></div><details class="attempt-history"><summary>Saved solution & reflections</summary>${savedAttempts(r.log.problemId)}</details></div>`;}).join('')}</section>`:`<section class="card empty"><div class="empty-icon">${icon('repeat')}</div><h2>${all.length?'No reviews '+(reviewFilter==='due'?'due now.':'in this view.'):'Your first review starts with a first attempt.'}</h2><p>${all.length?'Your saved solutions remain available under All scheduled.':'Finish a session to save your work and schedule a review.'}</p><button class="button primary" data-view="today">Continue practice ${icon('arrow')}</button></section>`}`);
}
function journal(){
 const next=recommendation();
 const nextProblem=state.active?problem(state.active.problemId):next?.problem;
 const nextTopic=state.active?topicById(state.active.topicId):next?.topic;
 const continueCard=`<section class="card continue-card"><div><span class="tiny-label">${state.active?'READY WHEN YOU ARE':'YOUR NEXT STEP'}</span><h2>${escape(nextProblem?.name||'Choose your next problem')}</h2><p>${nextTopic?`${escape(nextTopic.name)} · ${nextProblem!.rating} rating · ${state.active?state.active.duration:state.duration} min`:'Browse the library or refresh the catalog for more practice.'}</p></div><button class="button primary" ${nextProblem?'data-action="start"':'data-view="library"'}>${icon('play')}${state.active?'Resume session':nextProblem?'Continue practice':'Browse problems'}${icon('arrow')}</button></section>`;
 const stats=bandStats(),independent=state.logs.filter(qualified).length,minutes=Math.round(state.logs.reduce((s,l)=>s+l.seconds/60,0));
 shell(`${heading('EVIDENCE OVER GUESSWORK','Watch the small steps add up.','Practice ratings are earned per category. They are not a prediction of your contest rating.')}${continueCard}<div class="stats-grid"><div class="card stat"><span>Focused practice</span><strong>${minutes}<small> min</small></strong></div><div class="card stat"><span>Qualifying attempts</span><strong>${independent}</strong></div><div class="card stat"><span>Categories explored</span><strong>${stats.covered}<small> / ${topics.length}</small></strong></div><div class="card stat"><span>Categories with cleared bands</span><strong>${stats.cleared}</strong></div></div><section class="card"><div class="section-heading"><h2>Progress by category</h2><span>Current practice band</span></div><div class="band-chart">${topics.map(t=>{const p=progress(state,t.id);return `<div class="band-row"><button class="text-button" data-evidence="${t.id}">${t.name} · ${p.fresh}/3</button><div class="band-bar"><i style="width:${Math.min(100,(p.band-700)/17)}%"></i></div><strong>${p.band}</strong><small>${p.cleared?'cleared '+p.cleared:'uncalibrated'}</small></div>`;}).join('')}</div></section><div class="section-heading spaced"><h2>Your practice journal</h2><span>${state.logs.length} attempts</span></div>${state.logs.length?[...state.logs].reverse().map(l=>`<article class="card log-card"><div class="log-top"><div><span class="tiny-label">${shortDate(l.finishedAt)} · ${topicById(l.topicId).name} · ${l.review?'REVIEW':'NEW ATTEMPT'}</span><h3>${escape(problem(l.problemId)?.name||l.problemId)}</h3></div><span class="rating">${l.rating}</span></div><div class="log-meta"><span>${Math.round(l.seconds/60)} min</span><span>${l.outcome==='independent'?'Independent':l.outcome==='assisted'?'Used help':'Still learning'}</span><span>${l.verified?'✓ Acceptance verified':'Acceptance not verified'}</span><span>${qualified(l)?'Qualifies for progression':'Review / practice credit only'}</span></div>${l.notes?`<p class="saved-notes">${escape(l.notes)}</p>`:'<p class="muted">No reflection saved.</p>'}${l.code?`<details><summary>Saved C++ solution</summary><pre class="compiler-output">${escape(l.code)}</pre></details>`:''}${l.blocker?`<div class="tiny">Main blocker: ${escape(l.blocker)}</div>`:''}</article>`).join(''):'<section class="card empty"><h3>Your progress starts here.</h3><p>No invented streaks or inflated skill scores. Your first session will create the first entry.</p><button class="button secondary" data-view="today">Start a session</button></section>'}`);
}
function evidenceView(){
 const t=topicById(evidenceTopic),p=progress(state,t.id),all=categoryProblems(state,catalog.problems,t.id);
 const bands=[...new Set([p.band,...all.map(r=>r.rating).filter((rating):rating is number=>rating!==undefined)])].sort((a,b)=>a-b);
 const rows=all.filter(r=>(evidenceBand==='all'||r.rating===Number(evidenceBand))&&(categoryScope==='all'||(categoryScope==='attempted'?r.attempts.length>0:!!r.active)));
 shell(`${heading('YOUR PROBLEMS, ONE CATEGORY AT A TIME',escape(t.name),'Open a problem’s attempt history to revisit each solution, reflection, and result.',`<button class="text-button" data-view="journal">Back to progress ${icon('arrow')}</button>`)}<div class="category-summary"><div class="category-stat"><strong>${all.filter(r=>r.attempts.length).length}</strong><span>Problems attempted here</span></div><div class="category-stat"><strong>${all.reduce((n,r)=>n+r.attempts.length,0)}</strong><span>Saved attempts in this category</span></div><div class="category-stat"><strong>${p.fresh}/3 <small>at ${p.band}</small></strong><span>${p.reviewed?'Independent repeat complete':'Independent repeat still needed'}</span></div></div>${ladders.some(l=>l.topicId===t.id)?`<button class="button secondary" data-topic-ladder="${t.id}">Follow a concept ladder ${icon('arrow')}</button>`:''}<div class="filters category-controls"><label>Category <select id="evidence-topic">${topics.map(topic=>`<option value="${topic.id}" ${t.id===topic.id?'selected':''}>${topic.name}</option>`).join('')}</select></label><label>Rating <select id="evidence-band"><option value="all" ${evidenceBand==='all'?'selected':''}>All ratings</option>${bands.map(b=>`<option value="${b}" ${String(b)===evidenceBand?'selected':''}>${b}${b===p.band?' · Current band':''}</option>`).join('')}</select></label><label>Show <select id="category-scope"><option value="all" ${categoryScope==='all'?'selected':''}>All recorded problems</option><option value="attempted" ${categoryScope==='attempted'?'selected':''}>Attempted in Fieldwork</option><option value="active" ${categoryScope==='active'?'selected':''}>In progress</option></select></label></div><p class="tiny">${rows.length} problems · Attempt counts cover saved sessions in this category. Imported accepts do not include Codeforces submission history.</p><div class="category-problem-grid">${rows.map(r=>{
 const e=r.evidence;
 return `<article class="card category-problem-card" data-category-problem="${escape(r.problemId)}"><div class="problem-card-head"><span class="tiny-label">${escape(r.problemId)}</span><span class="rating">${r.rating??'Unrated'}</span></div><h2>${escape(r.name)}</h2><div class="problem-card-meta"><span>${r.attempts.length} saved ${r.attempts.length===1?'attempt':'attempts'}</span>${r.active?'<span>Draft in progress</span>':''}${r.imported?'<span>Accepted on Codeforces</span>':''}</div><p class="completion-status">${e?.manual?'Counted · Manual credit':e?.automatic?'Counted · Verified independent solve':escape(e?.reasons.join(' · ')||'No completed attempt yet.')}${e?.counted?` · ${r.rating} band`:''}</p><div class="problem-card-actions">${problemLadderLink(r.problemId)}${e?`<button class="button secondary small" data-credit="${escape(r.problemId)}" data-credit-band="${r.rating}" ${e.automatic&&!e.manual?'disabled':''}>${e.manual?'Undo manual credit':e.automatic?'Counts toward 3':'Count this solve'}</button>`:''}${r.active?'<button class="button secondary small" data-action="start">Resume draft</button>':problem(r.problemId)?`<button class="text-button" data-category-practice="${escape(r.problemId)}">${r.attempts.length?'Practice again':'Practice'} ${icon('arrow')}</button>`:''}</div><details class="problem-attempts"><summary>Attempt history (${r.attempts.length})</summary>${r.attempts.length?r.attempts.map((l,i)=>`<details class="attempt-detail"><summary>Attempt ${r.attempts.length-i} · ${escape(new Date(l.finishedAt).toLocaleString())} · ${l.outcome==='independent'?'Independent':l.outcome==='assisted'?'Used help':'Unfinished'}</summary><div class="attempt-facts"><span>${l.review?'Review':'First practice'}</span><span>${Math.round(l.seconds/60)} min</span><span>${l.rating} rating</span><span>${l.verified?'Acceptance verified':'Acceptance not verified'}</span></div><p class="attempt-notes">${escape(l.notes||'No reflection recorded.')}</p>${l.blocker?`<p class="tiny">Blocker: ${escape(l.blocker)}</p>`:''}${l.code?.trim()&&l.code.trim()!==starter.trim()?`<details><summary>Saved C++ code</summary><pre class="attempt-source"><code>${escape(l.code)}</code></pre><button class="button secondary small" data-copy-saved="${escape(l.id)}">Copy this attempt’s code</button></details>`:'<p class="tiny">No solution saved in this attempt (empty or starter only).</p>'}</details>`).join(''):`<p class="tiny">${r.active?'Your draft is saved. Finish the session to add it to this history.':'Imported acceptance only. Source code and past submissions were not imported.'}</p>`}</details></article>`;
 }).join('')}</div>${!rows.length?'<section class="card empty"><h2>No problems match this view.</h2><p>Choose another filter, sync Codeforces, or start a practice session.</p></section>':''}<p class="footnote">Manual credit counts one distinct solve for the displayed rating and category. Undo it at any time. Advancing still requires three completions and one independent repeat after 48 hours.</p>`);
}
function leetcodeSettings(){
 const lc=state.leetcode;
 return `<section class="card"><h2>LeetCode connection</h2><p>Track recent accepted solutions alongside your Codeforces practice.</p><label class="field-label" for="leetcode-handle">LeetCode username</label><input id="leetcode-handle" value="${escape(leetcodeDraft??lc?.username??'')}" placeholder="Your LeetCode username" autocomplete="off" spellcheck="false" ${leetcodeBusy?'disabled':''}><button class="button primary spaced" data-action="sync-leetcode" ${leetcodeBusy?'disabled':''}>${leetcodeBusy?'Syncing LeetCode…':'Save username & sync'}</button>${lc?`<p>Tracking ${link('https://leetcode.com/u/'+encodeURIComponent(lc.username)+'/',escape(lc.username))}</p><div class="account-stats"><div><strong>${lc.totals.all}</strong><span>Total solved</span></div><div><strong>${Object.keys(lc.accepted).length}</strong><span>Observed problems</span></div></div><p class="tiny">Last synced ${escape(new Date(lc.syncedAt).toLocaleString())}</p>`:''}<p class="tiny">Public sync observes recent accepts and keeps those previously seen for this username. It cannot reconstruct all older solutions or import source code. If a past solve is missing, mark it practiced in its ladder. LeetCode difficulty does not change Codeforces rating bands.</p><button class="text-button wide" data-view="ladders">Explore concept ladders ${icon('arrow')}</button></section>`;
}
function lcPracticeKey(slug:string){return `lc:${state.leetcode?.username.toLowerCase()||'unlinked'}:${slug}`;}
function ladderCompleted(){
 const completed=new Set<string>(state.profile.solved.map(p=>'cf:'+key(p)));
 for(const slug of Object.keys(state.leetcode?.accepted||{}))completed.add('lc:'+slug);
 for(const ladder of ladders)for(const step of ladder.steps)for(const p of step.leetcode)if(state.ladderPractice?.[lcPracticeKey(p.slug)])completed.add('lc:'+p.slug);
 return completed;
}
function ladderView(){
 const completed=ladderCompleted(),chosen=ladders.find(l=>l.id===selectedLadder);
 const problemKeys=(step:typeof ladders[number]['steps'][number])=>[...step.codeforcesIds.map(id=>'cf:'+id),...step.leetcode.map(p=>'lc:'+p.slug)];
 const finished=(step:LadderStep)=>problemKeys(step).every(id=>completed.has(id));
 type LadderStep=typeof ladders[number]['steps'][number];
 if(!chosen){shell(`${heading('LEARN THE PATTERN, THEN EXTEND IT','Concept ladders.','Each step builds on the previous idea. Explain the invariant, solve the exercises, then move to the next variation.')}<div class="rules-banner"><div><strong>Two platforms, one learning path</strong></div><p>Links are practice exercises, not claims of equal difficulty. Codeforces retains its numeric ratings; LeetCode retains Easy / Medium / Hard. Ladder completion tracks practice separately from category promotion.</p></div><div class="category-problem-grid">${ladders.map(l=>{const done=l.steps.filter(finished).length;return `<article class="card ladder-card"><span class="tiny-label">${escape(topicById(l.topicId).name)}</span><h2>${escape(l.title)}</h2><p>${escape(l.description)}</p><ol>${l.steps.map(step=>`<li>${escape(step.title)}</li>`).join('')}</ol><div class="problem-card-actions"><span>${done}/${l.steps.length} steps practiced</span><button class="button primary small" data-ladder="${l.id}">${done===l.steps.length?'Revisit ladder':'Continue ladder'} ${icon('arrow')}</button></div></article>`;}).join('')}</div>`);return;}
 const next=nextLadderStep(chosen,completed);
 shell(`${heading('BUILD ONE IDEA ON THE LAST',escape(chosen.title),escape(chosen.description),'<button class="text-button" data-action="all-ladders">All ladders</button>')}<p class="tiny">${state.leetcode?'LeetCode: '+escape(state.leetcode.username):'Connect your LeetCode username in Settings to sync recent accepts.'} · Marking practiced is a personal record, not acceptance verification.</p><div class="ladder-steps">${chosen.steps.map((step,i)=>`<details class="card ladder-step" ${step===next||(!next&&i===0)?'open':''}><summary><span class="step-number">${i+1}</span><strong>${escape(step.title)}</strong><span>${finished(step)?'Practiced':step===next?'Next step':'To practice'}</span></summary><p>${escape(step.buildsOn)}</p><p>${escape(step.concept)}</p><div class="ladder-exercises">${step.codeforcesIds.map(id=>{const p=problem(id);return p?`<article><div><span class="tiny-label">CODEFORCES · ${id} · ${p.rating}</span><h3>${escape(p.name)}</h3><p>${completed.has('cf:'+id)?'Accepted on Codeforces':'Not accepted in synced history'}</p></div><div class="problem-card-actions">${link(`https://codeforces.com/problemset/problem/${p.contestId}/${p.index}`,'Open problem '+icon('external'))}<button class="button secondary small" data-ladder-cf="${id}" data-ladder-topic="${chosen.topicId}">Practice in Fieldwork</button></div></article>`:'';}).join('')}${step.leetcode.map(p=>`<article><div><span class="tiny-label">LEETCODE · ${p.difficulty}</span><h3>${escape(p.title)}</h3><p>${state.leetcode?.accepted[p.slug]?'Accepted · observed in sync':state.ladderPractice?.[lcPracticeKey(p.slug)]?'Marked practiced by you':'Not observed in recent sync'}</p></div><div class="problem-card-actions">${link('https://leetcode.com/problems/'+p.slug+'/', 'Open LeetCode '+icon('external'))}${!state.leetcode?.accepted[p.slug]?`<button class="button secondary small" data-lc-practice="${p.slug}">${state.ladderPractice?.[lcPracticeKey(p.slug)]?'Undo practiced':'Mark practiced'}</button>`:''}</div></article>`).join('')}</div></details>`).join('')}</div>`);
}
async function syncLeetCode(current=false){
 if(leetcodeBusy)return;
 const field=current?null:$<HTMLInputElement>('#leetcode-handle');
 if(current&&!state.leetcode){view='settings';render();$('#leetcode-handle').focus();return;}
 const username=(field?.value??state.leetcode?.username??'').trim();if(field)leetcodeDraft=username;
 if(!/^[a-zA-Z0-9_-]{1,40}$/.test(username)){toast('Enter a valid LeetCode username.');return;}
 leetcodeBusy=true;render();
 try{const profile=window.fieldwork?await window.fieldwork.syncLeetCode(username):await fetch('/api/leetcode?username='+encodeURIComponent(username)).then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.error||'LeetCode sync unavailable.');return data;});
 if(!validLeetCode(profile))throw new Error('LeetCode returned incomplete data. Saved progress is unchanged.');
 state.leetcode=mergeLeetCode(state.leetcode,profile);if(!current)leetcodeDraft=null;save();toast('LeetCode synced. Recent accepts updated; older unseen solves may be missing.');
 }catch(e){toast((e as Error).message);}finally{leetcodeBusy=false;render();}
}
function settings(){
 shell(`${heading('MAKE THIS FIT YOUR LIFE','Your practice, your pace.','A 4–6 hour week is a starting target. Thirty minutes is enough on a busy PhD day.')}<div class="settings-grid">${leetcodeSettings()}<section class="card"><h2>Daily rhythm</h2><p>Choose your default. Extend a session by 15 minutes when you have more time.</p><div class="segmented settings-duration">${[30,45,60].map(m=>`<button data-duration="${m}" class="${state.duration===m?'selected':''}">${m} min</button>`).join('')}</div><label class="field-label" for="initial-band">Starting band for calibration</label><select id="initial-band" ${state.logs.length?'disabled':''}>${[800,900,1000].map(n=>`<option ${n===state.initialBand?'selected':''}>${n}</option>`).join('')}</select><p class="tiny">Defaults to the first eligible band at or above 800. This is a practice target, not an earned rating. Locked after your first logged attempt.</p><h3 class="spaced">Strict promotion</h3><ul class="plain-list"><li>3 different independent solves at the exact rating.</li><li>Each accepted after the session started and completed within 25 minutes.</li><li>No hints or editorials; reasoning and tests checked.</li><li>1 accepted repeat of a qualifying solve after at least 48 hours.</li><li>Only the focus category advances, normally by 100 points.</li></ul></section><section class="card"><h2>Codeforces connection</h2><p>Public history only. No password or API key needed.</p><label class="field-label" for="handle">Codeforces handle</label><input id="handle" value="${escape(handleDraft??state.profile.handle)}" placeholder="Your Codeforces username" autocomplete="off" spellcheck="false" ${busy?'disabled':''}><p class="tiny">Tracking <strong>${escape(state.profile.handle)}</strong>. Enter a handle and press Enter or Save handle &amp; sync. Each account keeps its own sessions and progress.</p><div class="account-stats"><div><strong>${state.profile.rating??'—'}</strong><span>Current rating</span></div><div><strong>${state.profile.maxRating??'—'}</strong><span>Peak rating</span></div><div><strong>${state.profile.solved.length}</strong><span>Distinct accepts</span></div></div><button class="button primary" data-action="sync" ${busy?'disabled':''}>${icon('repeat')}${busy?'Syncing…':'Save handle & sync'}</button><p class="tiny">Last snapshot: ${escape(new Date(state.profile.syncedAt).toLocaleString())}. Historical accepts are excluded from new problem recommendations, but never grant automatic progression.</p><div class="divider"></div><h3>Problem catalog</h3><p>${catalog.problems.length.toLocaleString()} rated problems · ${shortDate(new Date(catalog.updatedAt).getTime())}</p><button class="button secondary" data-action="catalog" ${busy?'disabled':''}>Refresh official ratings ${icon('repeat')}</button></section><section class="card"><h2>Your data stays with you</h2><p>${window.fieldwork?'Progress is saved atomically in your local app data folder.':'This browser preview saves to this browser’s local storage. Export here and import in Electron to move your progress.'} Export a backup whenever you want.</p><div class="button-row"><button class="button secondary" data-action="export">${icon('download')}Export backup</button><label class="button secondary file-button">Import backup<input type="file" id="import" accept="application/json,.json"></label></div><p class="tiny">Import replaces current progress after confirmation. The backup includes your handle, notes, session history, and timer.</p></section><section class="card"><h2>A reference, not a race</h2><p>The Academy provides the broad topic map. Fieldwork uses Codeforces tags and official problem ratings to keep your next step small.</p>${link(academyUrl,`YouKn0wWho Academy topic list ${icon('external')}`)}<p class="tiny">18 practice categories cover all 11 major sections. This is not a reproduction of every Academy subtopic. Concept ladders add LeetCode practice for interview patterns. This still does not cover every interview skill, such as API design.</p></section></div>`);
}
function sessionView(){
 const a=state.active;if(!a){view='today';return today();}const p=problem(a.problemId);if(!p){toast('This problem is missing from the catalog. Restore its catalog or use a backup.');view='settings';return settings();}
 const t=topicById(a.topicId),n=elapsed(a),budget=a.duration*60;
 const recalled=state.logs.filter(l=>l.notes&&l.problemId!==a.problemId).at(-1);
 shell(`${heading(a.review?'RETRIEVAL SESSION':'FOCUS SESSION','One problem. Your full attention.',`${t.name} · ${a.review?'Rebuild it without your old solution.':'Write the simplest correct approach before optimizing.'}`,`<button class="text-button" data-view="today">Save & leave ${icon('arrow')}</button>`)}<div class="focus-layout"><section class="card problem-workspace"><div class="section-heading"><span class="tiny-label">CODEFORCES · ${p.id}</span>${rated(p)}</div><h2 class="problem-title">${escape(p.name)}</h2><p class="problem-intro">Read the original statement, code in your editor, and submit on Codeforces. Fieldwork keeps your practice focused and measures the result.</p><div class="button-row">${link(`https://codeforces.com/problemset/problem/${p.contestId}/${p.index}`,`<span class="button primary">Open problem ${icon('external')}</span>`)}</div><div class="divider"></div><details class="recall"><summary>01 · Recall an idea <span>5 min</span></summary><p>Without looking anything up, explain a pattern from your last session. Name its invariant, complexity, and one edge case.</p>${recalled?`<details><summary>Reveal your previous reflection</summary><p class="saved-notes">${escape(recalled.notes)}</p></details>`:'<p class="tiny">For your first session: describe how you would test an off-by-one error in an array loop.</p>'}</details>${a.review&&state.logs.some(l=>l.problemId===a.problemId)?`<details class="attempt-history" data-saved-review><summary>Reveal saved reflections & code (counts as help)</summary>${savedAttempts(a.problemId)}</details>`:''}<div class="workspace-notes"><label for="notes">02 · Your scratchpad <span>Autosaved</span></label><textarea id="notes" placeholder="What is the brute-force approach?\nWhat observation makes it faster?\nWhy is it correct?\n\nKeep the insight you want to remember…">${escape(a.notes)}</textarea></div><div class="editor-toolbar"><h3>C++ workspace</h3><span>C++17 · Vim · i to insert · Esc for Normal</span></div><div id="code-editor" class="code-editor"></div><div class="editor-actions"><button class="button secondary" data-action="copy-code" title="Copy the entire C++ source">Copy code</button><button class="button secondary" data-action="paste-code" title="Paste at the cursor or replace selected text; undo with u">Paste code</button><button class="button secondary" data-action="select-code">Select all</button><button class="button secondary" data-action="check-code">Check C++</button><button class="button secondary" data-action="submit-code">Copy & open submission ${icon('external')}</button><button class="button secondary" data-action="sync" ${busy?'disabled':''}>${busy?'Syncing…':'Sync acceptance'}</button></div><p class="clipboard-hint">Copy code copies everything. Paste inserts at your cursor or replaces your selection. Cmd/Ctrl+A, C, and V work with Vim enabled.</p><div id="compiler-output" class="compiler-output hidden" role="status"></div><p class="connection-notice">${escape(state.profile.handle)} · ${((state.profile.accepted[a.problemId]||0)>=a.startedAt)?'Accepted submission verified for this session':'Submit on Codeforces, then sync acceptance here'}. Syntax checks use your local compiler; Codeforces runs the official tests.</p><div class="checklist"><h3>03 · Before you call it solved</h3>${['I can explain why the algorithm is correct.','I checked time and space complexity against the constraints.','I tested boundaries, duplicates, and a case that breaks my first idea.'].map((label,i)=>`<label><input type="checkbox" data-check="${i}" ${a.checks[i]?'checked':''}><span>${label}</span></label>`).join('')}</div><div class="session-end"><button class="button primary" data-action="reflect">Finish & reflect ${icon('arrow')}</button><button class="text-button" data-action="defer">Park this problem</button></div></section><aside><section class="card timer-card"><span class="tiny-label">TIME TO THINK</span><div id="timer" class="timer">${formatTime(Math.max(0,budget-n))}</div><p id="timer-caption">${n>=budget?'Your planned session is complete. Finish or extend.':`${a.duration}-minute session · ${a.runningSince===null?'paused':'in progress'}`}</p><div class="button-row"><button class="button secondary" data-action="pause">${a.runningSince===null?'Resume timer':'Pause timer'}</button><button class="button secondary" data-action="extend">+15 min</button></div><div id="checkpoint" class="checkpoint ${n>=25*60?'':'hidden'}"><strong>25-minute checkpoint</strong><p>Still testing concrete ideas? Keep going. Circling? Use a hint or study the editorial, then log an assisted attempt. Longer solves remain valuable practice but do not qualify for promotion.</p></div></section><section class="card session-coach"><span class="tiny-label">WHEN YOU HIT A WALL</span><h3>Make the next question smaller.</h3><ol><li>What does brute force do?</li><li>Which work is repeated?</li><li>What stays true as the input changes?</li><li>Can a tiny counterexample disprove the idea?</li></ol><button class="button secondary wide" data-action="help" ${a.help?'disabled':''}>${a.help?'Help use recorded':'I used a hint / editorial'}</button><p class="tiny">Reading the named technique or a solution counts as help. General thinking prompts above do not.</p><details class="topic-hints"><summary data-action="reveal-tags">Reveal problem tags (counts as help)</summary><p>${escape(p.tags.join(' · '))}</p></details></section><section class="quiet-note">${icon('leaf')}<p>You can stop after this problem.<br>Consistency has room for a busy day.</p></section></aside></div>${reflection?reflectionModal():''}`);
}
function reflectionModal(){const draft=state.active!.reflectionDraft;return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="reflection-title"><div class="eyebrow">KEEP THE LESSON</div><h2 id="reflection-title">How did this attempt go?</h2><p>Your answer changes the next review, not your worth as a programmer.</p><label class="field-label" for="outcome">Result</label><select id="outcome"><option value="independent" ${state.active!.help?'disabled':''}>Solved independently</option><option value="assisted" ${state.active!.help?'selected':''}>Solved with a hint / editorial</option><option value="stuck">Not solved yet</option></select><label class="field-label" for="blocker">Main friction</label><select id="blocker"><option value="">No major blocker</option><option>Finding the approach</option><option>Proving correctness</option><option>Implementation</option><option>Edge cases / debugging</option><option>Complexity</option></select><label class="field-label" for="takeaway">One thing to recognize next time</label><textarea id="takeaway" placeholder="When I see…, I should try…">${escape(draft?.notes??state.active!.notes)}</textarea><p class="tiny">Draft autosaved. Acceptance is verified by syncing Codeforces. An unverified solve stays in your journal and review queue but cannot raise a band.</p><div class="button-row"><button class="button primary" data-action="save-result">Save session ${icon('check')}</button><button class="button secondary" data-action="cancel-reflect">Keep working</button></div></section></div>`;}
function render(){({today,map:skillMap,library,reviews:reviewQueue,journal,settings,ladders:ladderView,evidence:evidenceView,session:sessionView} as Record<string,()=>void>)[view]?.();}
function begin(p:Problem,topicId:string,review=false){
 if(state.active){view='session';toast('Finish or park your current problem before starting another.');return render();}
 state.active={problemId:p.id,topicId,rating:p.rating,startedAt:Date.now(),elapsed:0,runningSince:Date.now(),duration:state.duration,review,help:false,notes:'',checks:[false,false,false],code:starter};focusTopic='';reflection=false;view='session';save();render();window.scrollTo(0,0);
}
function pause(){const a=state.active!;if(a.runningSince===null)a.runningSince=Date.now();else {a.elapsed=elapsed(a);a.runningSince=null;}save();render();}
async function sync(current=false){
 if(busy)return;const field=current?null:$<HTMLInputElement>('#handle');const handle=(field?field.value:state.profile.handle).trim();
 if(field)handleDraft=handle;
 if(!/^[a-zA-Z0-9_.-]{3,24}$/.test(handle)){toast('Enter a valid Codeforces handle.');return;}
 busy=true;render();
 try{
  let profile:Profile;
  if(window.fieldwork)profile=await window.fieldwork.sync(handle);
  else {const r=await fetch(`/api/codeforces?handle=${encodeURIComponent(handle)}`);const body=await r.json();if(!r.ok)throw new Error(body.error||'Sync unavailable.');profile=body;}
  trackProfile(state,profile);if(!current)handleDraft=null;focusTopic='';save();toast(`Synced ${profile.solved.length} accepted problems. Practice evidence updated.`);
 }catch(e){toast((e as Error).message||'Codeforces is unavailable. Saved progress is unchanged.');}finally{busy=false;render();}
}
async function refreshCatalog(){if(busy)return;busy=true;render();try{
 const updated=window.fieldwork?await window.fieldwork.catalog():await fetch('/api/catalog').then(async r=>{if(!r.ok)throw new Error('Catalog refresh is unavailable. Open the Electron app or try again later.');return r.json();});
 if(!Array.isArray(updated.problems)||!updated.problems.length)throw new Error('The refreshed catalog was empty. Existing problems are preserved.');
 catalog=updated;state.catalog=catalog;state.bands=ratingLadders(catalog.problems);save();toast('Official problem ratings refreshed. Logged attempts keep their original rating.');
 }catch(e){toast((e as Error).message);}finally{busy=false;render();}}
function finish(){
 const a=state.active!;const outcome=$<HTMLSelectElement>('#outcome').value as Outcome;const seconds=elapsed(a);
 state.logs.push({id:crypto.randomUUID(),problemId:a.problemId,topicId:a.topicId,rating:a.rating,startedAt:a.startedAt,finishedAt:Date.now(),seconds,outcome:a.help&&outcome==='independent'?'assisted':outcome,help:a.help,verified:(state.profile.accepted[a.problemId]||0)>=a.startedAt,review:a.review,notes:$<HTMLTextAreaElement>('#takeaway').value,blocker:$<HTMLSelectElement>('#blocker').value,checks:[...a.checks],code:a.code});
 state.active=null;reflection=false;view='journal';save();render();toast('Session saved. Your next review is scheduled. Sync Codeforces to verify acceptance.');
}
function bind(){
 document.querySelectorAll<HTMLElement>('[data-category-card]').forEach(el=>el.onclick=event=>{if((event.target as HTMLElement).closest('button,a,input,select,summary'))return;el.querySelector<HTMLButtonElement>('[data-evidence]')?.click();});

 document.querySelectorAll<HTMLElement>('[data-ladder]').forEach(el=>el.onclick=()=>{selectedLadder=el.dataset.ladder!;view='ladders';render();window.scrollTo(0,0);});
 document.querySelectorAll<HTMLElement>('[data-topic-ladder]').forEach(el=>el.onclick=()=>{selectedLadder=ladders.find(l=>l.topicId===el.dataset.topicLadder)?.id||'';view='ladders';render();window.scrollTo(0,0);});
 document.querySelectorAll<HTMLElement>('[data-ladder-cf]').forEach(el=>el.onclick=()=>{const p=problem(el.dataset.ladderCf!);if(p)begin(p,el.dataset.ladderTopic!,state.logs.some(l=>l.problemId===p.id)||state.profile.solved.some(s=>key(s)===p.id));});
 document.querySelectorAll<HTMLElement>('[data-lc-practice]').forEach(el=>el.onclick=()=>{const slug=el.dataset.lcPractice!,id=lcPracticeKey(slug);state.ladderPractice={...state.ladderPractice,[id]:!state.ladderPractice?.[id]};save();render();});
 const lcHandle=$<HTMLInputElement>('#leetcode-handle');if(lcHandle){lcHandle.oninput=()=>{leetcodeDraft=lcHandle.value;};lcHandle.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();void syncLeetCode();}};}

 document.querySelectorAll<HTMLElement>('[data-evidence]').forEach(el=>el.onclick=()=>{evidenceTopic=el.dataset.evidence!;evidenceBand='all';categoryScope='all';view='evidence';render();window.scrollTo(0,0);});
 const evidenceCategory=$<HTMLSelectElement>('#evidence-topic');if(evidenceCategory)evidenceCategory.onchange=()=>{evidenceTopic=evidenceCategory.value;evidenceBand='all';categoryScope='all';render();};
 const evidenceRating=$<HTMLSelectElement>('#evidence-band');if(evidenceRating)evidenceRating.onchange=()=>{evidenceBand=evidenceRating.value;render();};
 const scope=$<HTMLSelectElement>('#category-scope');if(scope)scope.onchange=()=>{categoryScope=scope.value;render();};
 document.querySelectorAll<HTMLElement>('[data-category-practice]').forEach(el=>el.onclick=()=>{const p=problem(el.dataset.categoryPractice!);if(p)begin(p,evidenceTopic,state.logs.some(l=>l.problemId===p.id)||state.profile.solved.some(s=>key(s)===p.id));});
 document.querySelectorAll<HTMLElement>('[data-repeat]').forEach(el=>el.onclick=()=>{const topicId=el.dataset.repeat!,candidate=repeatCandidate(state,catalog.problems,topicId);if(candidate){begin(candidate.problem,topicId,true);if(!candidate.ready)toast('Repeat started early. It can count after the original solve is at least 48 hours old.');}else toast('Complete three problems before starting a repeat.');});
 document.querySelectorAll<HTMLElement>('[data-credit]').forEach(el=>el.onclick=()=>{
  const id=el.dataset.credit!,band=Number(el.dataset.creditBand),row=completionEvidence(state,catalog.problems,evidenceTopic,band).find(r=>r.problemId===id);if(!row)return;
  const credits=state.manualCredits||[];
  if(row.manual)state.manualCredits=credits.filter(c=>!(c.topicId===evidenceTopic&&c.rating===band&&c.problemId===id));
  else if(!row.automatic)state.manualCredits=[...credits,{topicId:evidenceTopic,rating:band,problemId:id,grantedAt:Date.now()}];
  save();render();toast(row.manual?'Manual credit removed. Progress recalculated.':'Solve credited. Category progress updated.');
 });
 document.querySelectorAll<HTMLElement>('[data-view]').forEach(el=>el.onclick=()=>{if(view==='session'&&state.active?.runningSince!==null&&state.active){state.active.elapsed=elapsed(state.active);state.active.runningSince=null;save();}view=el.dataset.view!;reflection=false;render();window.scrollTo(0,0);});
 document.querySelectorAll<HTMLElement>('[data-external]').forEach(el=>el.onclick=e=>{e.preventDefault();openExternal(el.dataset.external!);});
 document.querySelectorAll<HTMLElement>('[data-duration]').forEach(el=>el.onclick=()=>{state.duration=Number(el.dataset.duration);save();render();});
 document.querySelectorAll<HTMLElement>('[data-train]').forEach(el=>el.onclick=()=>{focusTopic=el.dataset.train!;const next=recommendation();if(next)begin(next.problem,next.topic.id,next.review);else toast('No unseen problem at this exact band. Refresh the catalog or choose a review.');});
 document.querySelectorAll<HTMLElement>('[data-pick]').forEach(el=>el.onclick=()=>{
  const p=problem(el.dataset.pick!)!;const t=filterTopic?topicById(filterTopic):topics.find(t=>p.tags.some(tag=>t.tags.includes(tag)));
  if(!t){toast('This problem has no mapped category. Choose another problem.');return;}
  const review=state.logs.some(l=>l.problemId===p.id)||state.profile.solved.some(s=>key(s)===p.id);
  begin(p,t.id,review);if(p.rating!==progress(state,t.id).band)toast('Free practice: only exact-band qualifying solves count toward promotion.');
 });
 document.querySelectorAll<HTMLElement>('[data-review-filter]').forEach(el=>el.onclick=()=>{reviewFilter=el.dataset.reviewFilter!;render();});
 document.querySelectorAll<HTMLElement>('[data-copy-saved]').forEach(el=>el.onclick=async()=>{const l=state.logs.find(l=>l.id===el.dataset.copySaved);if(l?.code)try{await copyCode(l.code);toast('Saved solution copied.');}catch{toast('Could not copy. Select the saved code and use your system copy shortcut.');}});
 document.querySelectorAll<HTMLElement>('[data-restore-saved]').forEach(el=>el.onclick=()=>{const l=state.logs.find(l=>l.id===el.dataset.restoreSaved);if(l?.code&&state.active){replaceCode(l.code);state.active.help=true;save();toast('Saved solution loaded. This attempt counts as assisted; undo with u.');}});
 document.querySelectorAll<HTMLElement>('[data-review]').forEach(el=>el.onclick=()=>{const l=state.logs.find(l=>l.id===el.dataset.review)!;const p=problem(l.problemId);if(p)begin(p,l.topicId,true);});
 document.querySelectorAll<HTMLElement>('[data-action]').forEach(el=>el.onclick=async()=>{
  switch(el.dataset.action){
   case 'copy-code':try{await copyCode(state.active?.code??starter);toast('All code copied to your clipboard.');}catch{toast('Could not copy code. Select all and use your system copy shortcut.');}break;
   case 'paste-code':try{await pasteCode();toast('Pasted into the editor. Undo with u in Normal mode.');}catch(e){toast((e as Error).message);}break;
   case 'select-code':selectAllCode();break;
   case 'check-code':{
    const output=$('#compiler-output');output.classList.remove('hidden');output.textContent='Checking C++17…';
    if(!window.fieldwork){output.textContent='Local compiler checks are available in the Electron desktop app. This browser preview supports highlighting and completion.';break;}
    const source=state.active?.code??starter;el.setAttribute('disabled','');
    try{const result=await window.fieldwork.check(source);if(state.active?.code===source||(!state.active?.code&&source===starter)){showDiagnostics(result);const target=$('#compiler-output');if(target){target.classList.remove('hidden');target.textContent=result.output;}}else toast('Code changed during the check. Run Check C++ again.');}catch(e){output.textContent=(e as Error).message;}finally{el.removeAttribute('disabled');}break;
   }
   case 'submit-code':{
    const code=state.active?.code??starter;const p=problem(state.active!.problemId)!;
    try{if(window.fieldwork)await window.fieldwork.copy(code);else await navigator.clipboard.writeText(code);openExternal(`https://codeforces.com/contest/${p.contestId}/submit`);toast(`Code copied. Select problem ${p.index} and GNU C++17 or newer, paste, and submit. Then sync acceptance.`);}catch{toast('Could not copy code. Select it in the editor and copy manually.');}break;
   }
   case 'start':if(state.active){if(state.active.runningSince===null){state.active.runningSince=Date.now();save();}view='session';render();window.scrollTo(0,0);}else {const next=recommendation();if(next)begin(next.problem,next.topic.id,next.review);}break;
   case 'choose':view='map';render();break;
   case 'pause':pause();break;
   case 'extend':state.active!.duration+=15;save();render();toast('15 more minutes. Stay curious.');break;
   case 'help':state.active!.help=true;save();render();break;
   case 'reveal-tags':state.active!.help=true;save();break;
   case 'reflect':if(state.active!.runningSince!==null){state.active!.elapsed=elapsed(state.active!);state.active!.runningSince=null;}reflection=true;save();render();$('#outcome').focus();break;
   case 'cancel-reflect':reflection=false;state.active!.runningSince=Date.now();save();render();break;
   case 'save-result':finish();break;
   case 'defer':if(confirm('Park this problem for 7 days? Your scratchpad will be kept as an unfinished attempt.')){const a=state.active!;state.deferred[a.problemId]=Date.now()+7*DAY;state.logs.push({id:crypto.randomUUID(),problemId:a.problemId,topicId:a.topicId,rating:a.rating,startedAt:a.startedAt,finishedAt:Date.now(),seconds:elapsed(a),outcome:'stuck',help:a.help,verified:false,review:a.review,notes:a.notes,blocker:'Parked for later',checks:a.checks,code:a.code});state.active=null;view='today';save();render();}break;
   case 'sync':await sync();break;
   case 'sync-leetcode':await syncLeetCode();break;
   case 'sync-leetcode-current':await syncLeetCode(true);break;
   case 'all-ladders':selectedLadder='';view='ladders';render();break;
   case 'sync-current':await sync(true);break;
   case 'catalog':await refreshCatalog();break;
   case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`fieldwork-${localDay(Date.now())}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported.');break;}
  }
 });
 const handle=$<HTMLInputElement>('#handle');if(handle){handle.oninput=()=>{handleDraft=handle.value;};handle.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();void sync();}};}
 const prior=$<HTMLDetailsElement>('[data-saved-review]');if(prior)prior.ontoggle=()=>{if(prior.open&&state.active&&!state.active.help){state.active.help=true;save();const button=$('[data-action="help"]');button.textContent='Help use recorded';button.setAttribute('disabled','');toast('Saved solution revealed. This attempt will count as assisted.');}};
 const takeaway=$<HTMLTextAreaElement>('#takeaway');if(takeaway){
  const outcome=$<HTMLSelectElement>('#outcome'),blocker=$<HTMLSelectElement>('#blocker'),draft=state.active!.reflectionDraft;
  if(draft){outcome.value=state.active!.help&&draft.outcome==='independent'?'assisted':draft.outcome;blocker.value=draft.blocker;}
  const persist=()=>{state.active!.reflectionDraft={notes:takeaway.value,outcome:outcome.value as Outcome,blocker:blocker.value};save();};
  takeaway.oninput=persist;outcome.onchange=persist;blocker.onchange=persist;
 }
 const notes=$<HTMLTextAreaElement>('#notes');if(notes)notes.oninput=()=>{state.active!.notes=notes.value;save();};
 document.querySelectorAll<HTMLInputElement>('[data-check]').forEach(el=>el.onchange=()=>{state.active!.checks[Number(el.dataset.check)]=el.checked;save();});
 for(const [id,assign] of [['topic-filter',(v:string)=>{filterTopic=v;}],['rating-filter',(v:string)=>{filterRating=v;}],['status-filter',(v:string)=>{filterStatus=v;}]] as const){const el=$<HTMLSelectElement>('#'+id);if(el)el.onchange=()=>{assign(el.value);library();};}
 const search=$<HTMLInputElement>('#search');if(search)search.oninput=()=>{query=search.value;library();const input=$<HTMLInputElement>('#search');input.focus();};
 const band=$<HTMLSelectElement>('#initial-band');if(band)band.onchange=()=>{if(!state.logs.length){state.initialBand=Number(band.value);save();}};
 const input=$<HTMLInputElement>('#import');if(input)input.onchange=async()=>{
  const file=input.files?.[0];if(!file)return;
  try{if(file.size>20_000_000)throw new Error('Backup is too large.');const imported:unknown=JSON.parse(await file.text());if(!validState(imported))throw new Error('This is not a valid Fieldwork backup. Current progress was not changed.');
   if(confirm('Replace your current progress with this backup? Export your current data first if you want to keep it.')){state=imported;catalog=state.catalog||catalog;state.bands=ratingLadders(catalog.problems);if(state.active){state.active.runningSince=null;}storageBroken=false;save();render();toast('Backup restored. Any active timer is paused.');}
  }catch(e){toast((e as Error).message);}input.value='';
 };
}
function updateClock(){if(!state?.active)return;const a=state.active,n=elapsed(a);const timer=$('#timer');if(timer)timer.textContent=formatTime(a.duration*60-n);const caption=$('#timer-caption');if(caption)caption.textContent=n>=a.duration*60?'Your planned session is complete. Finish or extend.':`${a.duration}-minute session · ${a.runningSince===null?'paused':'in progress'}`;$('#checkpoint')?.classList.toggle('hidden',n<25*60);}
async function boot(){
 try{
  const [catalogData,seed]=await Promise.all([fetch('/catalog.json').then(r=>r.json()),fetch('/seed.json').then(r=>r.json())]);catalog=catalogData;
  const blank:State={version:1,duration:30,initialBand:800,profile:{...seed,accepted:seed.accepted||{}},logs:[],active:null,deferred:{}};
  const raw=window.fieldwork?await window.fieldwork.load():localStorage.getItem('fieldwork-v1');
  if(raw){const parsed:unknown=JSON.parse(raw);if(!validState(parsed))throw new Error('Your saved progress could not be read. It has not been overwritten. Restore a valid backup after preserving the original progress file.');state=parsed;}else state=blank;
  if(state.catalog)catalog=state.catalog;
  state.bands=ratingLadders(catalog.problems);
  if(state.active?.runningSince){state.active.elapsed=elapsed(state.active);state.active.runningSince=null;save();}
  render();setInterval(updateClock,1000);
 }catch(e){$('#app').innerHTML=`<main class="boot-error"><h1>Let’s keep your progress safe.</h1><p>${escape((e as Error).message)}</p><p>Check the app files and reload. Existing saved data has not been replaced.</p></main>`;}
}
void boot();
